import{_ as e,o as a,c as l,aw as t}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Пирамида тестирования","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/testing/testing/pyramid/pyramid.md","filePath":"wiki/dev-commit/testing/testing/pyramid/pyramid.md"}'),r={name:"wiki/dev-commit/testing/testing/pyramid/pyramid.md"};function o(n,i,s,d,h,m){return a(),l("div",null,[...i[0]||(i[0]=[t('<h1 id="пирамида-тестирования" tabindex="-1">Пирамида тестирования <a class="header-anchor" href="#пирамида-тестирования" aria-label="Permalink to &quot;Пирамида тестирования&quot;">​</a></h1><hr><ul><li>Нижняя часть - это самые быстрые, простые и самые изолированные тесты</li><li>Верхняя часть - самые ресурсоемкие, самые медленные и охватывают всё приложение в целом</li></ul><h2 id="виды-тестов" tabindex="-1">Виды тестов <a class="header-anchor" href="#виды-тестов" aria-label="Permalink to &quot;Виды тестов&quot;">​</a></h2><ul><li>1 Unit Testing (Блочное)</li><li>Тестирование одного модуля в изоляции</li><li>2 Integration Testing (Интеграционное)</li><li>Тестирование группы взаимодействующих модулей</li><li>3 System Testing (Системное)</li><li>Тестирование системы в целом</li><li>Для небольших проектов это, как правило, ручное тестирование - запустил, пощелкал, убедился, что (не) работает. Можно автоматизировать</li><li>4 E2E Testing</li><li>Тестирование UI</li></ul><h3 id="system-testing-2-подхода-к-автоматизации" tabindex="-1">System Testing (2 подхода к автоматизации) <a class="header-anchor" href="#system-testing-2-подхода-к-автоматизации" aria-label="Permalink to &quot;System Testing (2 подхода к автоматизации)&quot;">​</a></h3><ol><li>Использовать вариацию MVC паттерна - Passive View и формализовать взаимодействие пользователя с GUI в коде. Тогда системное тестирование сводится к тестированию Presenter классов, а также логики переходов между View</li><li>Использовать специальные инструменты для записи действий пользователя. То есть в итоге запускается сама программа, но щелканье по кнопкам осуществляется автоматически</li></ol><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><h3 id="google-часто-предлагает-разделение70-20-10" tabindex="-1">Google часто предлагает разделение70/20/10 <a class="header-anchor" href="#google-часто-предлагает-разделение70-20-10" aria-label="Permalink to &quot;Google часто предлагает разделение70/20/10&quot;">​</a></h3><ul><li>70% unit тестов</li><li>20% интеграционных тестов</li><li>10% E2E тестов</li></ul><h3 id="информация-1" tabindex="-1">Информация <a class="header-anchor" href="#информация-1" aria-label="Permalink to &quot;Информация&quot;">​</a></h3><ol><li>Модульные тесты реализовывать быстрее, чем GUI тесты (время на разработку меньше). Модульные тесты отрабатывают быстрее, чем GUI</li><li>Модульные тесты дешевле, чем GUI тесты (однако, стремясь к вершине пирамиды, мы получаем большую уверенность в том, что все работает как ожидалось)</li><li>Тестирование должно быть разносторонним, но соотношение тестов должно быть таково, что модульных количественно больше, чем GUI</li></ol><h3 id="принципы" tabindex="-1">Принципы <a class="header-anchor" href="#принципы" aria-label="Permalink to &quot;Принципы&quot;">​</a></h3><ol><li>Писать тесты разной детализации</li><li>Чем выше уровень, тем меньше тестов</li></ol>',14)])])}const g=e(r,[["render",o]]);export{u as __pageData,g as default};
